async fn relay_readiness(
  state : Json,
  directory : String,
  git_enabled : Bool,
) -> RelayReadiness {
  let script =
    #|# orca-relay-readiness
    #|set -eu
    #|curl --disable --noproxy '*' --silent --max-time 1 --max-filesize 4096 --write-out '\n%{http_code}' http://localhost:12049/ready
  let started = @env.now()
  let result = @async.with_timeout(3000, async fn() {
    let (code, output, _) = @process.collect_output(
      workspace_program(state, "ssh"),
      extra_env=workspace_environment(state),
      cwd?=workspace_directory(state).map(path => path[:]),
      inherit_env=false,
      ssh_mux_options(state, directory) + [script],
    )
    if code != 0 {
      return RelayReadiness::Retry(
        if code == 28 {
          "http_timeout"
        } else {
          "transport_error"
        },
      )
    }
    let text = output.text().trim().to_owned()
    let lines = text.split("\n").to_array()
    let status = lines.last().unwrap_or("").to_owned()
    if status == "404" {
      return RelayReadiness::Unsupported
    }
    if status != "200" {
      return RelayReadiness::Retry(
        if status == "503" {
          "http_503"
        } else {
          "http_error"
        },
      )
    }
    let body = text[:text.length() - status.length()]
      .to_owned()
      .trim()
      .to_owned()
    let value = @json.parse(body) catch {
      _ => return RelayReadiness::Retry("schema_invalid")
    }
    if field(value, "version") != Some(Json::number(1)) {
      return RelayReadiness::Unsupported
    }
    if field(value, "owner") != field(state, "user") {
      return RelayReadiness::Retry("owner_mismatch")
    }
    for name in ["host_owner", "instance"] {
      if field(value, name) is Some(Json::String(value)) && value != "" {
        continue
      }
      return RelayReadiness::Retry("schema_invalid")
    }
    if git_enabled {
      let helper = "git config --global --get credential.helper | grep -F 'internal agent git-credentials' >/dev/null"
      let (code, _, _) = @process.collect_output(
        workspace_program(state, "ssh"),
        extra_env=workspace_environment(state),
        cwd?=workspace_directory(state).map(path => path[:]),
        inherit_env=false,
        ssh_mux_options(state, directory) + [helper],
      )
      if code == 1 {
        return RelayReadiness::WaitingForGitHelper
      }
      if code != 0 {
        return RelayReadiness::Retry("transport_error")
      }
    }
    RelayReadiness::Ready
  }) catch {
    @async.TimeoutError => RelayReadiness::Retry("ssh_timeout")
    _ => RelayReadiness::Retry("transport_error")
  }
  match result {
    Ready => ()
    WaitingForGitHelper =>
      save_diagnostic(
        "relay-probe",
        "pending",
        error_type="git_helper_unavailable",
        duration_ms=(@env.now() - started).to_double(),
        tunnel_directory=directory,
        recording=workspace_recording(state),
      )
    Retry(reason) =>
      save_diagnostic(
        "relay-probe",
        "failed",
        error_type=reason,
        duration_ms=(@env.now() - started).to_double(),
        tunnel_directory=directory,
        recording=workspace_recording(state),
      )
    Unsupported =>
      save_diagnostic(
        "relay-probe",
        "unsupported",
        error_type="readiness_unsupported",
        tunnel_directory=directory,
        recording=workspace_recording(state),
        tunnel_status(
          directory,
          "ownership-error",
          recording=workspace_recording(state),
        )
        return
      }
      if status != "Running" {
        if status == "Stopped" {
          idle_reset(state, "workspace_stopped")
        }
        monitoring = true
        tunnel_status(
          directory,
          if status == "Stopped" {
            "workspace-stopped"
          } else {
            "workspace-busy"
          },
          recording=workspace_recording(state),
        )
        return
      }
      monitoring = false
      if !adopted {
        stop_tunnel_master(state, directory, verify=true)
      }
      @fs.mkdir(
        required(state, "socketDirectory"),
        permission=0o700,
        allow_exist=true,
      )
      let sink = @process.redirect_to_file("/dev/null", shared=true)
      defer sink.close()
      let (errors, stderr) = @process.read_from_process()
      defer errors.close()
      let classified = group.spawn(
        async fn() { tunnel_errors(errors) },
        no_wait=true,
      )
      needs_cleanup = true
      let child = if adopted {
        save_diagnostic(
          "orca-tunnel",
          "adopted",
          tunnel_directory=directory,
          recording=workspace_recording(state),
        )
        None
      } else {
        Some(
          @process.spawn(
            group,
            workspace_program(state, "ssh"),
            extra_env=workspace_environment(state),
            cwd?=workspace_directory(state).map(path => path[:]),
            inherit_env=false,
            ssh_args(
              state,
              lease=required(state, "socketDirectory") + "/primary-proxy.lock",
            ) +
            [
              "-M",
              "-S",
              control_socket(state, directory),
              "-N",
              "-o",
              "ControlPersist=no",
              "-o",
              "ForkAfterAuthentication=no",
              "-o",
              "ExitOnForwardFailure=yes",
              "-o",
              "ServerAliveInterval=10",
              "-o",
              "ServerAliveCountMax=3",
            ] +
            forwarding,
            stdin=@process.redirect_from_file("/dev/null"),
            stdout=sink,
            stderr~,
            no_wait=true,
          ),
        )
      }
      adopted = false
      let git_enabled = @async.with_timeout(10000, async fn() {
        git_forwarding_enabled(state)
      })
      let mut next_probe = @env.now()
      let mut next_check = @env.now()

