///|
async fn devsy(state : Json, args : Array[String], stage : String) -> String {
  let (status, output, detail) = devsy_result(state, args, stage)
  guard status == 0 else {
    raise AdapterError(command_failure(stage, status, detail))
  }
  output
}

///|
fn saved_command(state : Json) -> Array[String] raise ConfigError {
  command_field(state, "recipeResult.userData").unwrap_or(["devsy"])
}

///|
fn proxy(
  state : Json,
  executable : String,
  services~ : Bool = true,
  lease~ : String = "",
) -> String raise {
  let args = ["env"]
  if workspace_directory(state) is Some(directory) {
    args.push("-C")
    args.push(directory)
  }
  for name in location_variables {
    args.push("-u")
    args.push(name)
  }
  for name in location_variables {
    if field(field(state, "devsyEnv").unwrap(), name)
      is Some(Json::String(value)) {
      args.push(name + "=" + value)
    }
  }
  (args +
  [executable, "--ssh-proxy", lease] +
  saved_command(state) +
  devsy_args(state) +
  [
    "workspace",
    "ssh",
    required(state, "workspaceId"),
    "--stdio",
    "--user",
    required(state, "user"),
  ] +
  (if services { [] } else { ["--start-services=false"] }))
  .map(quote)
  .join(" ")
  .replace_all(old="%", new="%%")
}

///|
async fn ssh_args(
  state : Json,
  services~ : Bool = true,
  lease~ : String = "",
) -> Array[String] {
  [
    "-o",
    "ProxyCommand=" + proxy(state, adapter_executable(), services~, lease~),
  ] +
  ssh_target_args(state)
      _ => raise AdapterError("Invalid saved tunnel port")
    }
    save_diagnostic(
      "recover-worker",
      if restart {
        "restart"
      } else if worker_alive(directory) {
        "reuse"
      } else {
        "restore"
      },
      tunnel_directory=directory,
      recording=workspace_recording(state),
    )
    ensure_ssh_worker(state, port, deadline~, restart~)
    if required(state, "connection") == "orca-server" {
      ignore(recover_server(state))
    }
    save_diagnostic(
      "recover",
      "success",
      tunnel_directory=directory,
      recording=workspace_recording(state),
    )
  })
}

///|
async fn workspace_status(state : Json) -> String {
  let result = @json.parse(
    @async.with_timeout(10000, async fn() {
      devsy(
        state,
        [
          "--result-format",
          "json",
          "workspace",
          "status",
          required(state, "workspaceId"),
          "--container-status=false",
        ],
        "workspace-status",
      )
    }),
  )
  match field(result, "state") {
    Some(Json::String("Running" | "Stopped" | "Busy" | "NotFound" as value)) =>
      value
    _ => raise AdapterError("Invalid workspace status")
  }
}

